@Component("businessUnit-subscriber")
public class BusinessUnitSubscriber extends BaseSubscriber {

	public BusinessUnitSubscriber() {
	}
	
    public SubscriptionQueryResult<List<BusinessUnit>, BusinessUnit> businessUnitSubscribe() {
        return queryGateway
                .subscriptionQuery(new FindAllBusinessUnitQuery(), 
                		ResponseTypes.multipleInstancesOf(BusinessUnit.class),
                		ResponseTypes.instanceOf(BusinessUnit.class));
    }

    public SubscriptionQueryResult<BusinessUnit, BusinessUnit> businessUnitSubscribe(@DestinationVariable UUID businessUnitId) {
        return queryGateway
                .subscriptionQuery(new FindBusinessUnitQuery(new LoadBusinessUnitFilter(businessUnitId)), 
                		ResponseTypes.instanceOf(BusinessUnit.class),
                		ResponseTypes.instanceOf(BusinessUnit.class));
    }





}

